  "filename": "page_workout.js",
  "content": "/*
  page_workout.js – Workout list page module
  Registers the "workouts" page with the ForgeAI shell.
  Expected ctx structure:
    ctx.root   – DOM element where the page should render
    ctx.api    – (path, options) => Promise<responseJson>
    ctx.search – optional search helper (not used here)
*/

(function () {
  // Utility: simple toast notification
  function showToast(message, type = "info") {
    const toast = document.createElement("div");
    toast.className = `toast toast-${type}`;
    toast.textContent = message;
    document.body.appendChild(toast);
    setTimeout(() => toast.remove(), 3000);
  }

  // Utility: create a modal element
  function createModal({ title, fields, onSubmit }) {
    const overlay = document.createElement("div");
    overlay.className = "modal-overlay";
    const modal = document.createElement("div");
    modal.className = "modal";
    const header = document.createElement("h2");
    header.textContent = title;
    modal.appendChild(header);

    const form = document.createElement("form");
    fields.forEach((f) => {
      const wrapper = document.createElement("div");
      wrapper.className = "form-field";
      const label = document.createElement("label");
      label.textContent = f.label;
      label.htmlFor = f.name;
      const input = document.createElement("input");
      input.type = f.type;
      input.id = f.name;
      input.name = f.name;
      if (f.required) input.required = true;
      wrapper.appendChild(label);
      wrapper.appendChild(input);
      form.appendChild(wrapper);
    });

    const actions = document.createElement("div");
    actions.className = "modal-actions";
    const submitBtn = document.createElement("button");
    submitBtn.type = "submit";
    submitBtn.textContent = "Save";
    submitBtn.className = "btn btn-primary";
    const cancelBtn = document.createElement("button");
    cancelBtn.type = "button";
    cancelBtn.textContent = "Cancel";
    cancelBtn.className = "btn btn-secondary";
    cancelBtn.addEventListener("click", () => overlay.remove());
    actions.appendChild(submitBtn);
    actions.appendChild(cancelBtn);
    form.appendChild(actions);

    form.addEventListener("submit", async (e) => {
      e.preventDefault();
      const data = {};
      fields.forEach((f) => {
        const val = form.elements[f.name].value.trim();
        data[f.name] = f.type === "number" ? Number(val) : val;
      });
      try {
        await onSubmit(data);
        overlay.remove();
      } catch (err) {
        showToast(err.message || "Operation failed", "error");
      }
    });

    modal.appendChild(form);
    overlay.appendChild(modal);
    document.body.appendChild(overlay);
  }

  // Render the workout list page
  async function renderWorkoutPage(ctx) {
    const { root, api } = ctx;
    root.innerHTML = ""; // clear previous content

    // Header + Add button
    const header = document.createElement("div");
    header.className = "page-header";
    const title = document.createElement("h1");
    title.textContent = "Workouts";
    const addBtn = document.createElement("button");
    addBtn.className = "btn btn-primary";
    addBtn.textContent = "+ Add Workout";
    header.appendChild(title);
    header.appendChild(addBtn);
    root.appendChild(header);

    const container = document.createElement("div");
    container.className = "workout-list";
    root.appendChild(container);

    // Loading skeleton
    const loading = document.createElement("div");
    loading.className = "loading-skeleton";
    loading.textContent = "Loading workouts…";
    container.appendChild(loading);

    // Fetch workouts
    let workouts = [];
    try {
      const resp = await api("/workouts", { method: "GET" });
      if (!resp.success) throw new Error("Failed to fetch workouts");
      workouts = resp.data || [];
    } catch (err) {
      container.innerHTML = "";
      const errDiv = document.createElement("div");
      errDiv.className = "error-state";
      errDiv.textContent = err.message || "Error loading workouts";
      container.appendChild(errDiv);
      showToast(err.message, "error");
      return;
    }

    // Remove loading skeleton
    loading.remove();

    if (workouts.length === 0) {
      const empty = document.createElement("div");
      empty.className = "empty-state";
      empty.innerHTML = `
        <p>No workouts found. Create your first workout to get started.</p>
        <button class="btn btn-primary" id="empty-add-btn">Add Workout</button>
      `;
      container.appendChild(empty);
      document.getElementById("empty-add-btn").addEventListener("click", openAddModal);
      return;
    }

    // Render cards
    const grid = document.createElement("div");
    grid.className = "card-grid";
    workouts.forEach((w) => {
      const card = document.createElement("div");
      card.className = "card workout-card";
      card.innerHTML = `
        <h3>${w.title}</h3>
        <p>${w.description}</p>
        <p><strong>Duration:</strong> ${w.duration_minutes} min</p>
        <p><strong>Difficulty:</strong> ${w.difficulty}</p>
        <button class="btn btn-link detail-btn" data-id="${w.id}">View Details</button>
      `;
      grid.appendChild(card);
    });
    container.appendChild(grid);

    // Detail navigation
    container.addEventListener("click", (e) => {
      if (e.target.matches('.detail-btn')) {
        const id = e.target.dataset.id;
        window.location.hash = `#/workouts/${id}`;
      }
    });

    // Add modal handler
    function openAddModal() {
      createModal({
        title: "Add New Workout",
        fields: [
          { name: "id", label: "ID", type: "text", required: true },
          { name: "title", label: "Title", type: "text", required: true },
          { name: "description", label: "Description", type: "text", required: true },
          { name: "duration_minutes", label: "Duration (minutes)", type: "number", required: true },
          { name: "difficulty", label: "Difficulty", type: "text", required: true }
        ],
        async onSubmit(formData) {
          const resp = await api("/workouts", { method: "POST", json: formData });
          if (!resp.success) throw new Error("Failed to create workout");
          showToast("Workout added", "success");
          // Refresh list
          renderWorkoutPage(ctx);
        }
      });
    }

    addBtn.addEventListener("click", openAddModal);
  }

  // Register the page with the global ForgeAI router
  if (window.ForgeAI && typeof window.ForgeAI.registerPage === "function") {
    window.ForgeAI.registerPage("workouts", renderWorkoutPage);
  } else {
    console.error("ForgeAI.registerPage not available – page_workout.js could not register.");
  }
})();
"
}
